        oxygenMgL.isAcceptableOrUnknown(data['oxygen_mg_l']!, _oxygenMgLMeta),
      );
    }
    if (data.containsKey('renewed_pct')) {
      context.handle(
        _renewedPctMeta,
        renewedPct.isAcceptableOrUnknown(data['renewed_pct']!, _renewedPctMeta),
      );
    }
    return context;
  }

