          ..write('supersedesId: $supersedesId, ')
          ..write('isTombstone: $isTombstone, ')
          ..write('visitId: $visitId, ')
          ..write('siteId: $siteId, ')
          ..write('pondId: $pondId, ')
          ..write('category: $category, ')
          ..write('ok: $ok, ')
          ..write('note: $note, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

